{
  "findings": [
    {
      "title": "Inconsistent staging criteria: AJCC 8th edition for HN tumors and UICC 9th edition for non-HN tumors, but UICC 9th edition does not exist (as of 2019)",
      "page": 33,
      "quote": "Staging is per AJCC 8th edition for HN tumors (Amin, 2017) and is per UICC 9th edition for non-HN tumors (O'Sullivan, 2015).",
      "severity": "major"
    },
    {
      "title": "Inconsistent study population: Section 6.1 says stage II to IV (M0) CSCC, but Section 7.2 says stage III to IV and selected stage II",
      "page": 30,
      "quote": "This is a single-arm, open label, multicenter phase 2 study for patients with stage II to IV (M0) CSCC",
      "severity": "major"
    },
    {
      "title": "Inconsistent study population: Section 7.2 says stage III to IV and selected stage II, but Section 7.2.1 says stage II to IV",
      "page": 33,
      "quote": "Patients with stage III to stage IV (M0) CSCC of the head/neck, extremity, or trunk, and selected patients with stage II CSCC (≥3 cm longest diameter lesion in an aesthetically-sensitive region)",
      "severity": "major"
    },
    {
      "title": "Inconsistent follow-up duration: Section 4 says total duration approximately 4 years and 3 months, but Section 6.1 says follow-up up to 3 years after Part 2 (which is up to 48 weeks) plus Part 1 (12 weeks) and screening (28 days) exceeds 4 years 3 months? Actually 3 years + 48 weeks + 12 weeks + 28 days = ~4 years 3 months, so consistent. No issue.",
      "page": 26,
      "quote": "a total duration of approximately 4 years and 3 months.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 34,
      "quote": "Prior radiation therapy for CSCC",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior treatment with anti-cancer systemic therapy within last 3 years, but prior anti-PD-1/PD-L1 is excluded at any time, which is redundant but not contradictory. No issue.",
      "page": 35,
      "quote": "Prior treatment with anti-cancer systemic therapy within the last 3 years prior to projected enrollment date",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 30,
      "quote": "Part 2 (adjuvant): Optional post-surgery cemiplimab treatment for up to 48 weeks (or radiation therapy, or observation only, at investigator discretion)",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 32,
      "quote": "At the discretion of the investigator, patients may alternatively receive adjuvant radiation therapy or enter an observation-only period.",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 28,
      "quote": "For patients who receive adjuvant radiation therapy or chemoradiation after surgery, the following treatment summary data will be captured in the eCRF:",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 27,
      "quote": "Change in post-surgical management plan in the screening period versus actual post-surgical management",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 28,
      "quote": "Post-surgical management plan (based on available clinical information if the patient were not enrolled in a clinical trial)",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion: Prior radiation therapy for CSCC is excluded, but adjuvant radiation therapy is allowed in Part 2",
      "page": 28,
      "quote": "If yes, radiation or chemoradiation (including name of concurrent systemic therapy agent, if applicable) or observation",
      "severity": "major"
    }
  ]
}
